	{1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0},
	{1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0}};
	
	
	// helper direction names (adjust if your decoder gives different values)
localparam logic [3:0] DIR_RIGHT = 4'd6;
localparam logic [3:0] DIR_UP    = 4'd8;
localparam logic [3:0] DIR_LEFT  = 4'd4;
localparam logic [3:0] DIR_DOWN  = 4'd2;

logic [10:0] srcX, srcY;                 // source coordinates into object_colors
logic recoverToggle;

// compute mapping and bounding box depending on direction
always_comb begin
    // defaults
    srcX = 0;
    srcY = 0;

    case (inputDirection)
        DIR_RIGHT: begin
            // no rotation
            srcX = offsetX;
            srcY = offsetY;
        end

        DIR_UP: begin
            // rotate 90° counter-clockwise (right -> up)
            // new dims: width' = OBJECT_HEIGHT_Y, height' = OBJECT_WIDTH_X
            srcX = OBJECT_WIDTH_X - 1 - offsetY;
            srcY = offsetX;
        end

        DIR_LEFT: begin
            // 180° rotation (right -> left)
            // src = (W-1 - dstX, H-1 - dstY)
            srcX = OBJECT_WIDTH_X - 1 - offsetX;
            srcY = OBJECT_HEIGHT_Y - 1 - offsetY;
        end

        DIR_DOWN: begin
            // rotate 90° clockwise (right -> down)
            // new dims: width' = OBJECT_HEIGHT_Y, height' = OBJECT_WIDTH_X
            srcX = offsetY;
            srcY = OBJECT_HEIGHT_Y - 1 - offsetX;
        end

        default: begin
            srcX = offsetX;
            srcY = offsetY;
        end
    endcase

end



//////////////////////////////////////////////////////////////////////////////////////////////////
logic [3:0] frameCnt;
logic       mouthOpen;

always_ff @(posedge clk) begin
    if (!resetN) begin
        frameCnt  <= 4'd0;
        mouthOpen <= 1'b0;
		  recoverToggle <= 0;
    end
    else if (startOfFrame) begin // assuming you have a vertical sync pulse per frame
        frameCnt <= frameCnt + 1;

        if (frameCnt == 4'd7) begin
            frameCnt  <= 4'd0;
            mouthOpen <= ~mouthOpen;  // toggle between open/close
        end
		  
		  if(recovering && frameCnt % 16 == 0) recoverToggle <= ~recoverToggle ;
		  else if(!recovering) recoverToggle <= 0;

    end
end

//////////////////////////////////////////////////////////////////////////////////////////////////


// synchronous output generation (keeps your original reset behavior)
// The bitmap lookup is a reset-free registered read so it maps to block RAM;
// the control bits are registered alongside it (with the reset) and the
// colour is picked from both, giving the same RGBout as the original register.
(* ram_style = "block" *) logic [1:0] sprite [0:255];  // {open, closed} at {srcY, srcX}
initial
    for (int y = 0; y < OBJECT_HEIGHT_Y; y++)
        for (int x = 0; x < OBJECT_WIDTH_X; x++)
            sprite[{y[3:0], x[3:0]}] = {object_colors_open[y][x], object_colors_closed[y][x]};

logic [1:0] spritePixel;
logic       drawQ, recoveringQ, recoverToggleQ, mouthOpenQ;

always_ff @(posedge clk)
    spritePixel <= sprite[{srcY[3:0], srcX[3:0]}];

always_ff @(posedge clk) begin
    if (!resetN) begin
        drawQ          <= 1'b0;
        recoveringQ    <= 1'b0;
        recoverToggleQ <= 1'b0;
        mouthOpenQ     <= 1'b0;
    end
    else begin
        // Safety: make sure srcX/srcY are in original object index ranges
        drawQ          <= InsideRectangle && (srcX < OBJECT_WIDTH_X) && (srcY < OBJECT_HEIGHT_Y);
        recoveringQ    <= recovering;
        recoverToggleQ <= recoverToggle;
        mouthOpenQ     <= mouthOpen;
    end
end

always_comb begin
    RGBout = TRANSPARENT_ENCODING; // default / out-of-range — don't draw
    if (drawQ) begin
        if (recoveringQ) RGBout = (recoverToggleQ || !spritePixel[1]) ? TRANSPARENT_ENCODING : PAC_ENCODING;
        else if (mouthOpenQ)
            RGBout = spritePixel[1] ? PAC_ENCODING : TRANSPARENT_ENCODING;
        else // mouth closed
            RGBout = spritePixel[0] ? PAC_ENCODING : TRANSPARENT_ENCODING;
    end
end

assign HitEdgeCode = 3'h0;


assign drawingRequest = InsideRectangle;

endmodule 